// Evaluating a strategy (slides p. 117–119, 125–128): nodes, time and memory of breadth-first search for a branching factor b
// and goal depth d, on a log scale, under AIMA's assumptions (§3.4.1): 10^6 nodes per second, 1 KB (1000 bytes) per node.
import { bar, card, md, num, s, slider, style, type FigOptions } from './shell';

const RATE = 1e6, BYTES = 1000, DMAX = 16, YMAX = 20, PX = 58, PY = 26, PW = 330, PH = 200, TX = 452;
/** Nodes generated by BFS (root not counted, as in the course's IDS table): early goal test b + … + b^d; late test, worst case, + b^{d+1} − b. */
export const early = (b: number, d: number) => { let n = 0; for (let i = 1; i <= d; i++) n += b ** i; return n; };
export const late = (b: number, d: number) => early(b, d) + b ** (d + 1) - b;

const unit = (x: number, us: [number, string][]) => { let [f, u] = us[0]; for (const [g, v] of us) if (x >= g) [f, u] = [g, v]; return `${num(x / f, 3)} ${u}`; };
const time = (n: number) => unit(n / RATE, [[1e-6, 'µs'], [1e-3, 'ms'], [1, 's'], [60, 'min'], [3600, 'hours'], [86400, 'days'], [86400 * 365, 'years']]);
const mem = (n: number) => unit(n * BYTES, [[1, 'B'], [1e3, 'KB'], [1e6, 'MB'], [1e9, 'GB'], [1e12, 'TB'], [1e15, 'PB'], [1e18, 'EB'], [1e21, 'ZB']]);
const count = (n: number) => (n < 1e7 ? Math.round(n).toLocaleString('en-US') : `${(n / 10 ** Math.floor(Math.log10(n))).toFixed(1)}e${Math.floor(Math.log10(n))}`);
const tcount = (n: number) => (n < 1e7 ? Math.round(n).toLocaleString('en-US').replace(/,/g, '{,}') : `${(n / 10 ** Math.floor(Math.log10(n))).toFixed(1)} \\times 10^{${Math.floor(Math.log10(n))}}`);
const REFS: [number, string][] = [[16e9 / BYTES, '16 GB of RAM'], [3600 * RATE, '1 hour'], [365 * 86400 * RATE, '1 year']];

export function mount(el: HTMLElement, opts: FigOptions = {}) {
  style('fig-ufe-css', CSS);
  const c = card(el, 'interactive', 'How fast BFS outgrows memory: nodes, time and memory against depth', '0 0 780 282');
  let b = 10, d = 10;
  if (early(10, 5) !== 111110 || late(10, 5) !== 1111100) console.error('search-cost: b = 10, d = 5 should give 111,110 and 1,111,100 (uninformed.md)');

  const X = (dd: number) => PX + (dd / DMAX) * PW, Y = (n: number) => PY + PH - (Math.min(YMAX, Math.max(0, Math.log10(n))) / YMAX) * PH;
  s(c.svg, 'text', { x: PX - 44, y: PY - 10, class: 'fg-t' }, 'nodes generated (log scale)');
  s(c.svg, 'rect', { x: PX, y: PY, width: PW, height: PH, class: 'ufe-box' });
  for (let e = 0; e <= YMAX; e += 4) {
    s(c.svg, 'line', { x1: PX, x2: PX + PW, y1: Y(10 ** e), y2: Y(10 ** e), class: 'ufe-grid' });
    const t = s(c.svg, 'text', { x: PX - 6, y: Y(10 ** e) + 4, class: 'fg-m', 'text-anchor': 'end' }, e ? '10' : '1');
    if (e) s(t, 'tspan', { dy: -6, 'font-size': '.72em' }, String(e));
  }
  for (let dd = 0; dd <= DMAX; dd += 4) s(c.svg, 'text', { x: X(dd), y: PY + PH + 15, class: 'fg-m', 'text-anchor': 'middle' }, String(dd));
  s(c.svg, 'text', { x: PX + PW, y: PY + PH + 30, class: 'fg-m', 'text-anchor': 'end' }, 'depth d of the shallowest goal');
  for (const [n, name] of REFS) {
    s(c.svg, 'line', { x1: PX, x2: PX + PW, y1: Y(n), y2: Y(n), class: 'ufe-ref' });
    s(c.svg, 'text', { x: PX + 4, y: Y(n) - 4, class: 'ufe-reft' }, name);
  }
  const lateL = s(c.svg, 'polyline', { class: 'ufe-late' }), earlyL = s(c.svg, 'polyline', { class: 'ufe-early' });
  const vline = s(c.svg, 'line', { y1: PY, y2: PY + PH, class: 'ufe-v' }), dot = s(c.svg, 'circle', { r: 5, class: 'ufe-dot' });
  s(c.svg, 'line', { x1: PX + 6, x2: PX + 26, y1: PY + PH + 46, y2: PY + PH + 46, class: 'ufe-early' });
  s(c.svg, 'text', { x: PX + 30, y: PY + PH + 50, class: 'fg-m' }, 'early goal test: b + … + bᵈ');
  s(c.svg, 'line', { x1: PX + 190, x2: PX + 210, y1: PY + PH + 46, y2: PY + PH + 46, class: 'ufe-late' });
  s(c.svg, 'text', { x: PX + 214, y: PY + PH + 50, class: 'fg-m' }, 'late test, worst case');

  // the AIMA-style table for the current b (early goal test)
  const head = s(c.svg, 'text', { x: TX, y: PY - 10, class: 'fg-t' });
  ['d', 'nodes', 'time', 'memory'].forEach((h, k) => s(c.svg, 'text', { x: TX + [14, 120, 210, 300][k], y: PY + 10, class: 'ufe-th', 'text-anchor': k ? 'end' : 'middle' }, h));
  const rows = Array.from({ length: 8 }, (_, i) => {
    const y = PY + 32 + i * 22;
    return { bg: s(c.svg, 'rect', { x: TX - 6, y: y - 15, width: 316, height: 21, rx: 5, class: 'ufe-row' }),
      t: [14, 120, 210, 300].map((x, k) => s(c.svg, 'text', { x: TX + x, y, class: 'ufe-td', 'text-anchor': k ? 'end' : 'middle' })) };
  });

  const knobs = bar(c);
  const bIn = slider(knobs, 'branching factor b', 2, 15, 1, b, v => { b = v; render(); });
  const dIn = slider(knobs, 'goal depth d', 1, DMAX, 1, d, v => { d = v; render(); });
  for (const inp of [bIn, dIn]) inp.addEventListener('change', () => opts.onEvent?.(`[${c.title}] ${c.cap.textContent}`));
  const pre = document.createElement('button');
  pre.className = 'btn sm';
  pre.textContent = 'b = 10, d = 5 (IDS table)';
  pre.onclick = () => { for (const [inp, v] of [[bIn, 10], [dIn, 5]] as const) { inp.value = String(v); inp.dispatchEvent(new Event('input')); } };
  knobs.append(pre);

  function render() {
    const pts = (f: (dd: number) => number) => Array.from({ length: DMAX }, (_, i) => `${X(i + 1)},${Y(f(i + 1))}`).join(' ');
    earlyL.setAttribute('points', pts(dd => early(b, dd)));
    lateL.setAttribute('points', pts(dd => late(b, dd)));
    for (const e of [vline]) { e.setAttribute('x1', String(X(d))); e.setAttribute('x2', String(X(d))); }
    dot.setAttribute('cx', String(X(d)));
    dot.setAttribute('cy', String(Y(early(b, d))));
    head.textContent = `BFS with b = ${b} (early goal test)`;
    rows.forEach((r, i) => {
      const dd = 2 * (i + 1), n = early(b, dd);
      [String(dd), count(n), time(n), mem(n)].forEach((v, k) => { r.t[k].textContent = v; });
      r.bg.classList.toggle('on', dd === d);
    });
    const n = early(b, d), nl = late(b, d);
    const first = (lim: number) => { for (let dd = 1; dd <= 40; dd++) if (early(b, dd) > lim) return dd; return 0; };
    const dRam = first(REFS[0][0]), dHour = first(REFS[1][0]);
    c.cap.innerHTML = md(`**b = ${b}, d = ${d}:** BFS with the early goal test generates $b + b^2 + \\dots + b^d$ = $\\mathbf{${tcount(n)}}$ nodes: ` +
      `**${time(n)}** at a million nodes per second and **${mem(n)}** at 1 KB per node, because BFS keeps every generated node. ` +
      `With the goal test at selection the worst case adds level $d+1$: $${tcount(nl)}$ nodes, about ${num(nl / n, 2)}× more. ` +
      `Memory runs out first: 16 GB is exceeded at depth **${dRam}**, while the time passes an hour only at depth **${dHour}**. ` +
      'Each extra level multiplies everything by about $b$: that is $O(b^d)$ on a log scale, a straight line whose slope is $\\log b$.');
  }
  render();
  return { destroy() {} };
}

const CSS = `
.ufe-box{fill:var(--panel-2);stroke:var(--border)}
.ufe-grid{stroke:var(--border);stroke-dasharray:2 4}
.ufe-ref{stroke:var(--bad);stroke-width:1.2;stroke-dasharray:5 4;opacity:.8}
.ufe-reft{font:600 10.5px var(--mono);fill:var(--bad)}
.ufe-early{fill:none;stroke:var(--accent);stroke-width:2.5}
.ufe-late{fill:none;stroke:var(--warn);stroke-width:2;stroke-dasharray:6 4}
.ufe-v{stroke:var(--text-2);stroke-width:1;stroke-dasharray:3 3;opacity:.6}
.ufe-dot{fill:var(--text);stroke:var(--panel);stroke-width:2}
.ufe-th{font-size:11.5px;font-weight:700;fill:var(--muted)}
.ufe-td{font:12px var(--mono);fill:var(--text-2)}
.ufe-row{fill:transparent;transition:fill .2s}
.ufe-row.on{fill:var(--accent-soft)}
`;
